def seq(x):
    a = [None, Fraction(x)]
    for n in range(1, 9):
        a.append(6 - a[n] if n % 2 else 2 * a[n])
    return a

def skill():
    x = Symbol('x')
    a1 = solve(Eq(16*x - 60, 20), x)[0]
    return a1 + (2*a1 - 6)

def standard():
    x = Symbol('x')
    a = [None, x]
    for n in range(1, 9):
        a.append(expand(6 - a[n] if n % 2 else 2 * a[n]))
    s = solve(Eq(a[9], 20), x)[0]
    return a[1].subs(x, s) + a[4].subs(x, s)

def unique():
    return [seq(x)[1] + seq(x)[4] for x in range(-60, 60) if seq(x)[9] == 20]
